			function onBtn6Click(e){
			    var btn6 = e.control;
			    var content = app.lookup("cmnHtmlEditorBbscttDtlCn").getValue();
			    
			    var byte = 0;
			    for (var i=0; i<content.length; i++){
			        (content.charCodeAt(i) > 127 ? byte+=3 : byte++);
			    
			    }
			    console.log(byte);
			    if(byte > 65000){
			        util.Msg.alert(app, "입력한 내용이 너무 깁니다.");
			        return false;
			        
			    }
			    
			    if(content.length == 0 || content.trim() == ""){
			        util.Msg.alert(app, "내용을 입력해주세요", function(){
			//            app.lookup("txa1").focus();
			        }, "내용입력");
			          console.log("val2"+content);
			          
			    } else {
			        // 입력 프리폼 유효성 체크
			        if (!util.validate(app, "grpBoardDtl")) return false;
			        
			        // 에디터값 변경사항 체크(에디터 사용시에만 적용)
			        var vcEditer = app.lookup("cmnHtmlEditorBbscttDtlCn");
			        var vsContent = vcEditer.getValue();
			        var vsBeforeCn = util.DataSet.getValue(app, "dsBoardList", 0, "BBSCTT_DTL_CN");
			        
			        if (vsContent == vsBeforeCn) {
			            // 입력 프리폼 변경사항 체크(프리폼에 데이터셋 바인딩시 동작)
			            if (!util.FreeForm.isModified(app, "grpBoardDtl", "MSG")) return false;
			        }
			        
			        // 저장시 에디터 값 데이터셋 삽입
			        util.DataSet.setValue(app, "dsBoardList", 0, "BBSCTT_DTL_CN", vsContent);
			        
			        doSave();
			        
			    }
			    
			}


